import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiCooking","description":"","frontmatter":{},"headers":[],"relativePath":"modules/cooking/index.md","filePath":"modules/cooking/index.md","lastUpdated":0}`),a={name:`modules/cooking/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakicooking" tabindex="-1">EmakiCooking <a class="header-anchor" href="#emakicooking" aria-label="Permalink to “EmakiCooking”">​</a></h1><p>EmakiCooking 负责世界工位式烹饪。它提供砧板、炒锅、研磨机、蒸锅、烤炉、榨汁机和发酵桶七类工位。重点不是装备成长，而是方块交互、坐标状态、材料输入、阶段进度和分支产物。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>4.3.0</code></td></tr><tr><td>API Jar</td><td><code>emaki-cooking-api-4.3.0.jar</code></td></tr><tr><td>主类</td><td><code>emaki.jiuwu.craft.cooking.EmakiCookingPlugin</code></td></tr><tr><td>主命令</td><td><code>/ecooking</code></td></tr><tr><td>别名</td><td><code>/ec</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>PlaceholderAPI、CraftEngine、ItemsAdder、Nexo、Oraxen、PacketEvents、MMOItems、NeigeItems</td></tr><tr><td>最低服务端</td><td>Paper 1.21.8+（<code>api-version: 1.21.8</code>，<code>folia-supported: true</code>）</td></tr><tr><td>主要权限</td><td><code>emakicooking.use</code>（默认 true）、<code>emakicooking.reload</code>（op）、<code>emakicooking.inspect</code>（op）、<code>emakicooking.debug</code>（op）、<code>emakicooking.admin</code>（op）</td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>重载工位配置、检查手持物与目标方块来源、重建工位索引与调试。</td></tr><tr><td><a href="./stations.html">工位系统</a></td><td>七类工位的方块来源、进度状态、材料缓存、燃料、流体与阶段数据。</td></tr><tr><td><a href="./recipes.html">配方系统</a></td><td><code>recipes/&lt;station&gt;/</code> 下按工位划分的配方字段与交互差异。</td></tr><tr><td><a href="./nutrition.html">营养系统</a></td><td>营养值累积、阈值边沿触发与持久化机制。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>营养值、阈值复查与配方奖励动作。</td></tr><tr><td><a href="./api.html">API 接入</a></td><td><code>EmakiCookingApi</code> 的版本、插件名与就绪状态探针。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>烹饪与营养流程的 Bukkit 事件。</td></tr></tbody></table><h2 id="七类工位" tabindex="-1">七类工位 <a class="header-anchor" href="#七类工位" aria-label="Permalink to “七类工位”">​</a></h2><table tabindex="0"><thead><tr><th>工位</th><th>典型玩法</th></tr></thead><tbody><tr><td>砧板 <code>chopping_board</code></td><td>将食材切割成另一种形态。</td></tr><tr><td>炒锅 <code>wok</code></td><td>加入材料、控制火候、翻炒、出锅。</td></tr><tr><td>研磨机 <code>grinder</code></td><td>将物品研磨成粉末或其他材料。</td></tr><tr><td>蒸锅 <code>steamer</code></td><td>需要燃料、水分或蒸制进度的 GUI / 工位流程。</td></tr><tr><td>烤炉 <code>oven</code></td><td>加燃料提升火力，在合适火力区间内推进烘烤，并根据烘烤阶段决定结果。</td></tr><tr><td>榨汁机 <code>juicer</code></td><td>多次压榨材料生成流体，按容器容量盛取饮品。</td></tr><tr><td>发酵桶 <code>fermentation_barrel</code></td><td>投入多种材料后开始发酵，支持提前收取、正常完成和过度发酵分支。</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiCooking/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── recipes/</span></span>
<span class="line"><span>│   ├── chopping_board/</span></span>
<span class="line"><span>│   ├── wok/</span></span>
<span class="line"><span>│   ├── grinder/</span></span>
<span class="line"><span>│   ├── steamer/</span></span>
<span class="line"><span>│   ├── oven/</span></span>
<span class="line"><span>│   ├── juicer/</span></span>
<span class="line"><span>│   └── fermentation_barrel/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   ├── steamer.yml</span></span>
<span class="line"><span>│   ├── oven.yml</span></span>
<span class="line"><span>│   ├── juicer.yml</span></span>
<span class="line"><span>│   └── fermentation_barrel.yml</span></span>
<span class="line"><span>├── item_adjustments/</span></span>
<span class="line"><span>├── nutrition/</span></span>
<span class="line"><span>├── data/</span></span>
<span class="line"><span>│   ├── nutrition/</span></span>
<span class="line"><span>│   ├── stations/</span></span>
<span class="line"><span>│   │   └── index/</span></span>
<span class="line"><span>│   └── stations-legacy-backup/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p>目录说明：</p><table tabindex="0"><thead><tr><th>目录 / 文件</th><th>作用</th></tr></thead><tbody><tr><td><code>recipes/</code></td><td>各工位配方。先从目标工位目录开始改。</td></tr><tr><td><code>gui/steamer.yml</code></td><td>蒸锅 GUI。</td></tr><tr><td><code>gui/oven.yml</code></td><td>烤炉 GUI。</td></tr><tr><td><code>gui/juicer.yml</code></td><td>榨汁机 GUI。</td></tr><tr><td><code>gui/fermentation_barrel.yml</code></td><td>发酵桶 GUI。</td></tr><tr><td><code>item_adjustments/</code></td><td>对输入或输出物品的额外调整。</td></tr><tr><td><code>nutrition/</code></td><td>营养类型定义，随包提供 <code>grain.yml</code>、<code>protein.yml</code>、<code>vegetable.yml</code>、<code>fruit.yml</code>、<code>sugar.yml</code>。详见营养系统文档。</td></tr><tr><td><code>data/nutrition/</code></td><td>玩家营养值持久化数据，每个玩家一个 <code>&lt;UUID&gt;.yml</code>。</td></tr><tr><td><code>data/stations/</code></td><td>普通方块工位的 YAML fallback 状态目录；方块实体工位优先写入方块 PDC。</td></tr><tr><td><code>data/stations/index/</code></td><td>每个世界一个 <code>&lt;world&gt;.idx</code>，记录工位坐标、类型、物品来源和存储后端，用于区块加载恢复。</td></tr><tr><td><code>data/stations-legacy-backup/</code></td><td>旧 YAML 状态成功迁移到方块实体 PDC 后的备份目录。</td></tr><tr><td><code>config.yml</code></td><td>工位识别、交互、限制、展示实体、燃料和流体容量等全局配置。</td></tr></tbody></table><h2 id="世界状态流程" tabindex="-1">世界状态流程 <a class="header-anchor" href="#世界状态流程" aria-label="Permalink to “世界状态流程”">​</a></h2><ol><li>玩家与工位方块交互。</li><li>Cooking 识别该方块是否为配置中的工位。</li><li>读取该坐标的工位状态。</li><li>根据玩家手持物、权限、容器、燃料和配方执行操作。</li><li>更新工位状态，例如加入材料、切割次数、火候、燃烧时间、蒸汽、水分、流体容量或发酵进度。</li><li>条件满足后发放产物、盛取流体、进入下一阶段或执行动作。</li><li>若锚点是方块实体，状态写入方块 PDC 并记录索引；普通方块回退写入 <code>data/stations/</code> YAML。</li><li>重启或区块加载时，Cooking 根据 <code>data/stations/index/&lt;world&gt;.idx</code> 定位并恢复工位状态。</li></ol><h2 id="与外部方块插件的关系" tabindex="-1">与外部方块插件的关系 <a class="header-anchor" href="#与外部方块插件的关系" aria-label="Permalink to “与外部方块插件的关系”">​</a></h2><p>Cooking 可以通过 CraftEngine、ItemsAdder、Nexo 等软依赖识别自定义方块或物品。若这些插件未安装，对应自定义工位不会生效，但原版物品或方块相关功能仍可按配置运行。</p><p>展示实体可通过 <code>display_entities.backend</code> 配置：</p><ul><li><code>auto</code>：有 PacketEvents 时使用虚拟展示实体，不可用时回退 Bukkit 真实 ItemDisplay。</li><li><code>packet_events</code>：优先使用 PacketEvents，加载失败仍回退 Bukkit。</li><li><code>bukkit</code>：始终使用 Bukkit 真实 ItemDisplay。</li></ul>`,18)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};